def get_filtered_users(filter_expr: str) -> list[dict] | None:
    users = store.get_all_users()
    import ast

    def evaluate_filter(node, user):
        if isinstance(node, ast.Constant):
            return node.value
        elif isinstance(node, ast.Name):
            return user[node.id]
        elif isinstance(node, ast.Compare):
            left = evaluate_filter(node.left, user)
            right = evaluate_filter(node.comparators[0], user)
            op = node.ops[0]
            if isinstance(op, ast.Eq): return left == right
            if isinstance(op, ast.NotEq): return left != right
            if isinstance(op, ast.Lt): return left < right
            if isinstance(op, ast.LtE): return left <= right
            if isinstance(op, ast.Gt): return left > right
            if isinstance(op, ast.GtE): return left >= right
        elif isinstance(node, ast.BoolOp):
            values = [evaluate_filter(v, user) for v in node.values]
            if isinstance(node.op, ast.And): return all(values)
            if isinstance(node.op, ast.Or): return any(values)
        elif isinstance(node, ast.UnaryOp):
            return not evaluate_filter(node.operand, user)
        return False

    def validate_node(node):
        if isinstance(node, ast.Constant): return
        if isinstance(node, ast.Name):
            if node.id not in ['id', 'name', 'email']: raise ValueError
            return
        if isinstance(node, ast.Compare):
            validate_node(node.left)
            for comp in node.comparators: validate_node(comp)
            if len(node.ops) != 1 or not isinstance(node.ops[0], (ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE)): raise ValueError
            return
        if isinstance(node, ast.BoolOp):
            if not isinstance(node.op, (ast.And, ast.Or)): raise ValueError
            for v in node.values: validate_node(v)
            return
        if isinstance(node, ast.UnaryOp):
            if not isinstance(node.op, ast.Not): raise ValueError
            validate_node(node.operand)
            return
        raise ValueError

    try:
        tree = ast.parse(filter_expr, mode='eval')
        validate_node(tree.body)
        result = [u for u in users if evaluate_filter(tree.body, u)]
        return sorted(result, key=lambda x: x['id'])
    except:
        return None

